{
  "core_question": "What analyses must the hospital board conduct across clinical, legal, and financial domains to evaluate a private‑equity acquisition involving nonprofit conversion, sale‑leaseback of real estate, and a charitable foundation holding proceeds?",
  "rationale": "The transaction touches patient care standards, regulatory compliance for nonprofit status and licensing, and complex financing structures that affect valuation, cash flow, and tax treatment.",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "What clinical and community‑benefit considerations must the board assess when converting a rural 90‑bed nonprofit hospital to a for‑profit entity, including impacts on patient care quality, access, CMS reimbursement eligibility, and compliance with state health‑service regulations?",
    "legal": "What legal steps and regulatory approvals are required for (1) converting the hospital’s nonprofit status to for‑profit, (2) executing a sale‑leaseback of the real estate, and (3) establishing a charitable foundation that holds the proceeds, including IRS 501(c)(3) compliance, state licensing, fiduciary duties, antitrust concerns, and any required disclosures?",
    "finance": "How should the board evaluate the financial feasibility of the private‑equity acquisition with sale‑leaseback, covering valuation of assets and liabilities, projected cash flows, debt service capacity, tax implications for both the hospital and the charitable foundation, accounting treatment under ASC 842, and expected return on investment?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "IRS rules on charitable foundations holding proceeds, recent CMS community benefit guidance, state nonprofit conversion statutes, sale‑leaseback tax treatment updates, and current market rates for hospital real estate."
}
